/// <reference path="./anime-torrent-provider.d.ts" />
/// <reference path="./core.d.ts" />

// ===================================================================
// VOTRE PASSKEY YGG ICI / YOUR YGG PASSKEY HERE
// ===================================================================
//
// 🔹 Vous pouvez le trouver ici / You can find it here :
//     https://www.yggtorrent.top/user/account
//
// 🛡️ Votre PASSKEY ne sera PAS enregistré. 
// Il ne sera utilisé que lors de la récupération des magnets,
// puis automatiquement intégré pour vous.
//
// 🛡️ Your PASSKEY will NOT be stored.
// It will only be used when retrieving magnets,
// and will then be automatically inserted for you.

// ===================================================================
const YGG_PASSKEY = "YOUR-PASSKEY"; 
// ===================================================================

interface ExtendedAnimeTorrent extends AnimeTorrent {
    id: number;
}

class Provider {

    apiUrl: string;
    passkey?: string;

    constructor() {
        this.apiUrl = "https://yggapi.eu";
        this.passkey = YGG_PASSKEY;
    }

    getSettings(): AnimeProviderSettings {
        return {
            canSmartSearch: true,
            smartSearchFilters: ["batch", "episodeNumber", "resolution", "query"],
            supportsAdult: true,
            type: "main",
        };
    }

    async search(opts: AnimeSearchOptions): Promise<AnimeTorrent[]> {
        const categories = [2178, 2179];
        const categoryParams = categories.map(c => `category_id=${c}`).join('&');
        const url = `${this.apiUrl}/torrents?q=${encodeURIComponent(opts.query)}&${categoryParams}`;
        return this.fetchFromApi(url);
    }

    async smartSearch(opts: AnimeSmartSearchOptions): Promise<AnimeTorrent[]> {
        const query = opts.query || opts.media.romajiTitle || opts.media.englishTitle || "";

        let categories = [2178, 2179];
        if (opts.media.format === "MOVIE") categories = [2178];
        else if (["TV", "TV_SHORT", "OVA", "ONA"].includes(opts.media.format || "")) categories = [2179];

        const categoryParams = categories.map(c => `category_id=${c}`).join('&');

        let url = `${this.apiUrl}/torrents?q=${encodeURIComponent(query)}&${categoryParams}`;
        if (opts.episodeNumber > 0 && !opts.batch) {
            url += `&episode=${opts.episodeNumber}`;
        }

        let torrents = await this.fetchFromApi(url);

        if (opts.resolution) {
            const targetRes = opts.resolution.replace('p', '');
            torrents = torrents.filter(t => (t.resolution || "").includes(targetRes));
        }
        if (opts.batch) {
             torrents = torrents.filter(t => t.isBatch);
        }

        return torrents;
    }

    async getTorrentMagnetLink(torrent: AnimeTorrent): Promise<string> {
        if (torrent.magnetLink) return torrent.magnetLink;
        if (!this.passkey || this.passkey === "YOUR-PASSKEY") {
            throw new Error("YGG Provider: Passkey is not configured.");
        }

        const torrentId = (torrent as ExtendedAnimeTorrent).id;
        if (!torrentId) throw new Error("Cannot find torrent ID.");

        const detailUrl = `${this.apiUrl}/torrent/${torrentId}`;
        const response = await fetch(detailUrl);
        if (!response.ok) throw new Error(`YGG Provider: Cannot get Torrent details (Status: ${response.status}).`);

        const detailData = await response.json<any>();
        const infoHash = detailData.hash;

        if (!infoHash) {
            console.error("YGG Provider: API didn't return a Hash for the torrent :", torrent.link);
            return "";
        }

        const displayName = encodeURIComponent(torrent.name);
        const trackerUrl = `http://tracker.p2p-world.net:8080/${this.passkey}/announce`;
        const tracker = encodeURIComponent(trackerUrl);

        const magnetLink = `magnet:?xt=urn:btih:${infoHash}&dn=${displayName}&tr=${tracker}`;

        torrent.magnetLink = magnetLink;
        torrent.infoHash = infoHash;

        return magnetLink;
    }

    async getTorrentInfoHash(torrent: AnimeTorrent): Promise<string> {
        if (torrent.infoHash) return torrent.infoHash;
        await this.getTorrentMagnetLink(torrent);
        return torrent.infoHash || "";
    }

    async getLatest(): Promise<AnimeTorrent[]> {
        const categories = [2178, 2179];
        const categoryParams = categories.map(c => `category_id=${c}`).join('&');
        const url = `${this.apiUrl}/torrents?${categoryParams}&order_by=uploaded_at`;
        return this.fetchFromApi(url);
    }

    /** pg   */
    async fetchFromApi(url: string): Promise<AnimeTorrent[]> {
        const response = await fetch(url);
        if (!response.ok) {
            throw new Error(`YGG Provider: API Error (Status: ${response.status}). Message: ${await response.text()}`);
        }
        const data = await response.json<any[]>();
        if (!data) return [];

        const torrentsWithMagnets = await Promise.all(
            data.map(async (apiTorrent: any) => {
                const torrent = this.apiResultToAnimeTorrent(apiTorrent);
                try {
                    await this.getTorrentMagnetLink(torrent);
                } catch (e) {
                    console.error(`Cannot retrieve magnet for "${torrent.name}":`, e);
                }
                return torrent;
            })
        );

        return torrentsWithMagnets;
    }

    private apiResultToAnimeTorrent(apiTorrent: any): ExtendedAnimeTorrent {
        const parsedInfo = this.parseTorrentName(apiTorrent.title);

        return {
            id: apiTorrent.id,
            name: apiTorrent.title,
            date: apiTorrent.uploaded_at,
            size: apiTorrent.size,
            formattedSize: "",
            seeders: apiTorrent.seeders,
            leechers: apiTorrent.leechers,
            downloadCount: apiTorrent.downloads,
            link: apiTorrent.link,
            downloadUrl: "",
            magnetLink: undefined,
            infoHash: undefined,
            resolution: parsedInfo.resolution,
            isBatch: parsedInfo.isBatch,
            episodeNumber: parsedInfo.episodeNumber,
            releaseGroup: parsedInfo.releaseGroup,
            isBestRelease: false,
            confirmed: false,
        };
    }

    private parseTorrentName(name: string): { resolution: string, episodeNumber: number, isBatch: boolean, releaseGroup: string | undefined } {
        let resolution = "", episodeNumber = -1, isBatch = false, releaseGroup: string | undefined = undefined;
        const resMatch = name.match(/[\[\(]?(\d{3,4})p[\]\)]?/i);
        if (resMatch) resolution = resMatch[1];
        const epMatch = name.match(/(?:s\d{1,2}[ex]|\s-\s|EP|Episode)\s?(\d{1,3})/i);
        if (epMatch) episodeNumber = parseInt(epMatch[1] || epMatch[2], 10);
        if (/\b(batch|integrale|collection|saison|season|pack|s\d{1,2}(?!e\d{1,2}))\b/i.test(name)) { isBatch = true; episodeNumber = -1; }
        const groupMatch = name.match(/^(?:\[([^\]]+?)\]|[\(\-]([^\)\-]+)$)/);
        if (groupMatch) releaseGroup = (groupMatch[1] || groupMatch[2] || "").trim();
        return { resolution, episodeNumber, isBatch, releaseGroup };
    }
}
